ALTER TABLE student_profiles ADD COLUMN github_user_id VARCHAR(40), ADD COLUMN github_username VARCHAR(100), ADD COLUMN github_access_token TEXT, ADD COLUMN github_avatar_url TEXT, ADD COLUMN github_connected_at TIMESTAMPTZ;
CREATE UNIQUE INDEX github_identity_unique ON student_profiles(github_user_id) WHERE github_user_id IS NOT NULL;
ALTER TABLE student_project_enrollments ADD COLUMN github_repo_url TEXT, ADD COLUMN github_repo_name VARCHAR(255), ADD COLUMN active_pr_url TEXT, ADD COLUMN active_pr_number INTEGER;
CREATE TABLE github_oauth_states (state_hash VARCHAR(64) PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, verifier TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE github_pull_requests (enrollment_id UUID NOT NULL REFERENCES student_project_enrollments(id) ON DELETE CASCADE, pr_number INTEGER NOT NULL, ticket_id UUID NOT NULL REFERENCES project_tickets(id), head_sha VARCHAR(64) NOT NULL, url TEXT NOT NULL, state VARCHAR(20) NOT NULL, review_status VARCHAR(30) NOT NULL DEFAULT 'PENDING', review_body TEXT, approved BOOLEAN NOT NULL DEFAULT FALSE, merged BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(enrollment_id,pr_number));
CREATE TABLE github_webhook_jobs (delivery_id VARCHAR(100) PRIMARY KEY, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, processed BOOLEAN NOT NULL DEFAULT FALSE, available_at TIMESTAMPTZ NOT NULL DEFAULT now());
